# shellcheck shell=sh
# review: a walkthrough of what was built, for the human to go through with the agent.
# Everything here is computed from git and the item, nothing is generated by a model.
[ $# -eq 0 ] || usage_die "usage: $NAME review"
need_repo
current_item || die "not on an item branch (see: $CMD status)"
item_phase

base=$(cfg sdd.base main)
mb=$(git merge-base "$base" HEAD)
# FR-22.4: the code this review shows, so ship can tell when it changes afterwards (this clone).
review_print >"$ST/checks/$ID.reviewed" || rm -f "$ST/checks/$ID.reviewed"
title=$IR_TITLE
echo "Review: $ID $ITYPE · $title   ($BRANCH → $base)"
echo "phase   $PHASE   ($WHY)"

ap=$IR_APPROVED
if [ "$(gate_level approved "$ITYPE")" = off ]; then
	:
elif [ -z "$ap" ]; then
	echo "plan    not approved"
elif approval_ok; then
	echo "plan    approved ${ap#* }, unchanged since"
else
	echo "plan    approved ${ap#* }, CHANGED since: re-approve or revert the plan"
fi

if check_passed_here "$ID"; then
	echo "check   ✓ passed for this exact code ($(sed -n 's/^at=//p' "$ST/checks/$ID"))"
elif [ -f "$ST/checks/$ID" ]; then
	echo "check   ✗ last result: $(sed -n 's/^result=//p' "$ST/checks/$ID"), or the code changed since; run: $CMD check"
else
	echo "check   never run; run: $CMD check"
fi
vline=$(verified_by)
echo "verify  ${vline:-Verified by: (missing)}"
pr=$(pr_note "$BRANCH")
[ -z "$pr" ] || echo "pr      $pr"

echo
echo "Commits"
git log --format='  %h %s' "$mb..HEAD"
echo
echo "Code changed (outside $SPECS/)"
git diff --stat=100 "$mb" -- . ":(exclude)$SPECS" | sed 's/^/ /'
git ls-files --others --exclude-standard | grep -v "^$SPECS/" | sed 's/^/  untracked: /'

# Sensitive files: dependencies, CI and agent config change what runs, with what, and who
# decides, so the human reads these diffs in full. Globs: [review] sensitive (core, user and
# project lists add up); this tool's own folder always counts. Names git still quotes (tabs,
# quotes, newlines) always count too: a hidden workflow must not slip past by its name.
globs=$(cfg_every review.sensitive)
sens=$({
	git -c core.quotePath=false diff --name-only "$mb"
	git -c core.quotePath=false ls-files --others --exclude-standard
} | sort -u | while IFS= read -r p; do
	set -f
	for g in '"*' $globs "$DIRNAME/*"; do
		# shellcheck disable=SC2254 # $g is a pattern on purpose
		case $p in ($g) echo "$p" && break ;; esac
	done
done)
if [ -n "$sens" ]; then
	echo
	echo "Sensitive files changed (read these diffs in full)"
	printf '%s\n' "$sens" | sed 's/^/  /'
fi

# section <heading>: the body of one "## " section of the item, guidance removed. Built runs
# up to "## Review", so headings an agent adds inside Built stay part of it.
section() {
	H=$1 awk '
		/^## / && !(on && ENVIRON["H"] == "Built" && $0 !~ /^## Review/) { on = (substr($0, 4) == ENVIRON["H"]); next }
		on' "$IFILE" | uncomment
}

frs=$(plan_frs)
if [ -n "$frs" ]; then
	echo
	echo "Requirements → where they are named outside $SPECS/ (tests should name the FR they prove)"
	unnamed=
	for fr in $frs; do
		# --untracked: agents often leave new tests uncommitted until the human ships.
		hits=$(git grep --untracked -nwF "$fr" -- . ":(exclude)$SPECS" 2>/dev/null | cut -d: -f1,2 | head -n 5 | paste -sd ' ' -)
		[ -n "$hits" ] || unnamed=1
		printf '  %-10s %s\n' "$fr" "${hits:-✗ not named anywhere}"
	done
	[ -z "$unnamed" ] || echo "  (✗ is for your review only: ship does not check it)"
fi

confirm=$(articles | awk -F '\t' '$2 == "review" { print "  [ ] " $1 " " $4 }')
if [ -n "$confirm" ]; then
	echo
	echo "Constitution: confirm each against this change (you, not the agent)"
	printf '%s\n' "$confirm"
fi
if [ "$ITYPE" = amendment ]; then
	echo
	echo "Constitution diff (against where this branch left $base)"
	git diff "$mb" -- "$CONST" | sed 's/^/  /'
fi

echo
sec=$(section "Security" | sed '/^[[:space:]]*$/d; s/^/  /')
if [ -n "$sec" ]; then
	echo "Security (from the plan)"
	printf '%s\n' "$sec"
	echo "  Check yourself (you, not the agent):"
	echo "  [ ] new input is validated, and every new path checks who may use it"
	echo "  [ ] no secrets in code, tests, specs or logs"
	echo "  [ ] new dependencies are real, needed and pinned"
	echo "  [ ] CI, agent config and $NAME itself changed only as planned"
	echo "  [ ] errors and logs leak no personal data or internals"
	echo "  [ ] the security pass under Built looked at this diff"
	echo
fi
echo "Built (written by the agent)"
section "Built" | sed '/^[[:space:]]*$/d; s/^/  /'
notes=$(section "Review (optional)" | sed '/^[[:space:]]*$/d; s/^/  /')
[ -z "$notes" ] || printf '\nReview notes (yours)\n%s\n' "$notes"
echo
echo "next    go through it together; changes → note them under \"## Review\" and the agent continues ($CMD next)"
echo "        satisfied → $CMD ship"
